export type EvalScore = { scoreId: string; evalId: string; traceId: string; targetType: string; targetId: string; scorer: string; label: string; score: number | null; passed: boolean | null; reason: string; modelId: string | null; cost: number | null; scoredAt: string; agentName: string | null; userMessage: string | null; promptVersion: { id: string; number: number } | null };
type ScoreRow = EvalScore;
// The deep-linked run comes from `evals.score`; same shape, one row.
type BaseScoreRow = ScoreRow;

const PAGE_SIZES = [25, 50, 100];

// Skeleton column spec for the loading body rows (see TableRowsSkeleton).
const SKELETON_COLS = [
  { icon: true, w: "w-64" },
