  { align: "right", w: "w-14" },
] as const;

/** 20/40/60/80th percentile thresholds (positive values only) for HeatCell. */
function quintiles(values: number[]): number[] {
  const v = values.filter((x) => x > 0).sort((a, b) => a - b);
  if (v.length === 0) return [];
  return [0.2, 0.4, 0.6, 0.8].map((q) => v[Math.floor(q * (v.length - 1))]!);
}

// Edit-dialog draft: the eval's name plus the subset the "How should it
// score?" fields can change (judge model + sample rate, or a check's params).
type EditDraft = {
  name: string;
  judgeModel: string;
  judgeProvider: Provider;
  sampleRate: string;
  passThreshold: string;
  substring: string;
  pattern: string;
  maxChars: string;
  promptOverride: string;
};

export type EvalDefinition = { id: string; name: string; presetId: string; scorerSource: "code" | "llm"; status: string; targetLevel: string; sampleRate: number; passThreshold: number; lastError: string | null; model: { modelId: string; provider: string } | null; config: { params?: Record<string, unknown>; promptOverride?: string; contextSpec?: Record<string, unknown> } | null; filters: { agentName?: string | null } | null };
export type EvalSeries = { scoreCount: number; passCount: number; verdictCount: number; scoredCount: number; avgScore: number | null; cost: number | null };
export type EvalUpdate = { evalId: string; name: string; sampleRate: number; passThreshold?: number; model?: { provider: Provider; modelId: string }; config: { promptOverride?: string; params?: Record<string, unknown>; contextSpec?: Record<string, unknown> } };
export type EvalJudgeInput = { prompt: string; truncated: boolean; preset: { id: string; name: string }; fields: Record<keyof typeof FIELD_LABEL, string | null>; segments: ({ kind: "text"; text: string } | { kind: "field"; field: keyof typeof FIELD_LABEL })[] };
type EvalDetailInputs = { traces: Record<string, TraceSpan[]>; judgeInputs: Record<string, EvalJudgeInput> };
const EvalDetailInputsContext = createContext<EvalDetailInputs>({ traces: {}, judgeInputs: {} });
export type EvalDetailBlockProps = { evalId?: string; definition?: EvalDefinition | null; presets?: { id: string; name: string; prompt: string }[]; providers?: { provider: string }[]; series?: EvalSeries[]; scores?: EvalScore[]; total?: number; isLoading?: boolean; focusedScoreId?: string | null; focusedScore?: EvalScore | null; onQueryChange?: (query: { page: number; pageSize: number; sort: { key: "score"; dir: "asc" | "desc" } | null; from: Date; to: Date }) => void; onUpdate?: (value: EvalUpdate) => void | Promise<void>; traces?: Record<string, TraceSpan[]>; judgeInputs?: Record<string, EvalJudgeInput> };
