        onClick={() => setOpen((o) => !o)}
        className={cn(
          "flex w-full cursor-pointer items-center gap-1.5 px-2 py-1.5 text-left text-xs transition-colors",
          failed
            ? "text-rose-600 dark:text-rose-400"
            : "text-muted-foreground hover:text-foreground",
        )}
      >
        <IconChevronRight
          className={cn(
            "size-3.5 shrink-0 transition-transform",
            open && "rotate-90",
          )}
        />
        {failed ? (
          <IconAlertTriangle className="size-3.5 shrink-0" />
        ) : (
          <IconTool className="size-3 shrink-0 fill-current" />
        )}
        <span className={cn(!failed && "text-muted-foreground/70")}>
          {label}
        </span>
        <span
          className={cn(
            "truncate font-medium",
            failed ? "text-rose-600 dark:text-rose-400" : "text-foreground",
          )}
        >
          {name}
        </span>
      </button>
      {open && (
        <JsonBlock
          data={data}
          className={cn(
            "border-t",
            failed ? "border-rose-500/30" : "border-border/60",
          )}
        />
      )}
    </div>
  );
}

/** Attachments arrive as base64 blobs. Rendering the bytes is never useful and
 * inlining megabytes of them wrecks the panel, so only the descriptors show. */
function FilePart({
  mediaType,
  filename,
}: {
  mediaType: string | null;
  filename: string | null;
}) {
  return (
    <div className="flex items-center gap-1.5 rounded-lg border border-border/60 bg-background/50 px-2 py-1.5 text-xs text-muted-foreground">
      <IconPaperclip className="size-3.5 shrink-0" />
      <span className="truncate font-medium text-foreground">
        {filename ?? "attachment"}
      </span>
      {mediaType && <span className="shrink-0">{mediaType}</span>}
    </div>
  );
}

function PartView({ part }: { part: Part }) {
  switch (part.kind) {
    case "text":
      return part.text.trim() ? <Prose>{part.text}</Prose> : null;
    case "reasoning":
      // Thinking, set apart from the answer — otherwise a model's scratch work
      // reads as the thing it actually said.
      return part.text.trim() ? (
        <div className="border-l-2 border-border pl-3 text-muted-foreground italic">
          <Prose>{part.text}</Prose>
        </div>
      ) : null;
    case "tool-call":
    case "tool-result":
    case "tool-error":
      return <ToolPart kind={part.kind} name={part.name} data={part.data} />;
    case "file":
      return <FilePart mediaType={part.mediaType} filename={part.filename} />;
    default:
      return <JsonBlock data={part.data} className="rounded-lg bg-muted" />;
  }
}

// Past this, a message is clamped behind a "Show more". Sized so a normal
// exchange never clamps but a 40k-token system prompt can't blow out the
// 420px-wide trace inspector.
const CLAMP_HEIGHT = 240;

// Assistant gets the same ghost as the Agents nav entry — one identity for
// "the model" everywhere. Tabler ships no filled wrench, so the tool icon
// self-fills via fill-current, here and on ToolPart headers.
const ROLE_ICONS: Record<string, typeof IconUserFilled> = {
  user: IconUserFilled,
  assistant: IconGhostFilled,
  system: IconSettingsFilled,
  tool: IconTool,
};

function MessageBlock({ message }: { message: Message }) {
  // System prompts are long, static, and almost never what you opened the panel
  // for — start them folded.
  const [expanded, setExpanded] = useState(message.role !== "system");
  const RoleIcon = message.role ? ROLE_ICONS[message.role] : undefined;
  // Tool and file parts are already collapsed behind their own disclosures, so
  // the height clamp adds nothing — worse, expanding a tool block inside a
  // clamped body used to surface a "Show more" that revealed a sliver. A
  // message of only such parts renders unclamped; opening a block shows all
  // of it.
  const selfCollapsing = message.parts.every(
    (p) =>
      p.kind === "tool-call" ||
      p.kind === "tool-result" ||
      p.kind === "tool-error" ||
      p.kind === "file",
  );
  const body = (
    <div className="flex flex-col gap-1.5">
      {message.parts.map((part, i) => (
        // biome-ignore lint/suspicious/noArrayIndexKey: parts are positional and static
        <PartView key={i} part={part} />
      ))}
    </div>
  );
  return (
    <div className="flex flex-col gap-1.5">
      {message.role && (
        <button
          type="button"
          onClick={() => setExpanded((e) => !e)}
          className="flex cursor-pointer items-center gap-1 self-start text-xs font-medium text-muted-foreground/70 group transition-colors hover:text-foreground"
        >
          <IconChevronRight
            className={cn(
              "size-3 shrink-0 transition-transform",
              expanded && "rotate-90",
            )}
          />
          {RoleIcon && (
            <RoleIcon className="mb-0.5 size-3 shrink-0 fill-current text-[#9E9E9E] transition-colors group-hover:text-foreground dark:text-[#787878] dark:group-hover:text-foreground" />
          )}
          {message.role.charAt(0).toUpperCase() + message.role.slice(1)}
        </button>
      )}
      {expanded && (selfCollapsing ? body : <ClampedBody>{body}</ClampedBody>)}
    </div>
  );
}

/** Caps its content's height behind a "Show more". Without this a single 40k-token
 * system prompt renders in full and buries every message after it. */
export function ClampedBody({
  children,
  maxHeight = CLAMP_HEIGHT,
  buttonClassName,
}: {
  children: React.ReactNode;
  /** Pixel height past which the content folds behind "Show more". */
  maxHeight?: number;
  /** Extra classes for the fold button — e.g. `DRAWER_BUTTON_CLASS` when
   * the body sits on a run drawer. */
  buttonClassName?: string;
}) {
  const [full, setFull] = useState(false);
  const [clamped, setClamped] = useState(false);
  const [inner, setInner] = useState<HTMLDivElement | null>(null);
  useEffect(() => {
    if (!inner) return;
    // Markdown and syntax highlighting both resolve asynchronously, so the
    // content's height isn't final on mount — watch it instead of measuring once.
    const check = () => setClamped(inner.scrollHeight > maxHeight + 8);
    check();
    const observer = new ResizeObserver(check);
    observer.observe(inner);
    return () => observer.disconnect();
  }, [inner, maxHeight]);
  return (
    <div className="flex flex-col gap-1">
      <div
        // The bleed (-m/p) keeps the children's outer shadow — the user
        // bubble's 0.5px ring in light — from being clipped at the edges.
        className="-m-1 overflow-hidden p-1"
        style={full ? undefined : { maxHeight }}
      >
        <div ref={setInner}>{children}</div>
      </div>
      {clamped && (
        <Button
          type="button"
          variant="secondary"
          size="sm"
          className={cn(
            "mt-3 w-full text-muted-foreground hover:text-foreground",
            buttonClassName,
          )}
          onClick={() => setFull((f) => !f)}
        >
          {/* text-current opts out of the Button variant's default icon
					    tint, which would otherwise disagree with the label color. */}
          <IconChevronDown
            className={cn("size-3.5 text-current", full && "rotate-180")}
          />
          {full ? "Show less" : "Show more"}
        </Button>
      )}
    </div>
  );
}

export function PayloadView({
  value,
  previousValue,
  foldBeforeLastUser,
  className,
}: {
  value: string;
  /** The equivalent payload from the previous LLM call in the same trace.
   * When it's an exact message-prefix of `value` (agent inputs grow by
   * appending), the unchanged messages fold away and only the new ones
   * render — re-scanning 30 repeated messages per step is the main cost of
   * reading an agent loop. Anything else (edited history, unparseable
   * payloads) falls back to the full view, so the delta never lies. */
  previousValue?: string | null;
  /** Fold every message before the last user turn, so a long conversation
   * opens on the exchange that matters (the latest question and what
   * followed it) with the history one click away. Used where the payload is
   * a whole transcript but the reader cares about one turn — e.g. an eval
   * run's scored input. Ignored when `previousValue` produces a delta. */
  foldBeforeLastUser?: boolean;
  className?: string;
}) {
  const { messages, shared, foldedByTurn } = useMemo(() => {
    const messages = toMessages(value);
    if (!messages) return { messages, shared: 0, foldedByTurn: false };
    if (previousValue) {
      const prev = toMessages(previousValue);
      if (prev) {
        return {
          messages,
          shared: unchangedPrefix(messages, prev),
          foldedByTurn: false,
        };
      }
    }
    if (foldBeforeLastUser) {
      let last = -1;
      for (let i = messages.length - 1; i >= 0; i--) {
        if (messages[i]?.role === "user") {
          last = i;
          break;
        }
      }
      return { messages, shared: Math.max(0, last), foldedByTurn: true };
    }
    return { messages, shared: 0, foldedByTurn: false };
  }, [value, previousValue, foldBeforeLastUser]);
  const [showEarlier, setShowEarlier] = useState(false);
  // The component instance survives span switches — fold back down for each
  // new payload.
  // biome-ignore lint/correctness/useExhaustiveDependencies: `value` is the reset trigger, not a used value
  useEffect(() => setShowEarlier(false), [value, previousValue, foldBeforeLastUser]);
  if (!messages) {
    // Not JSON — a plain (markdown) answer, or a payload truncated at the
    // storage cap. Either way the raw string is the honest thing to show.
    return (
      <div className={className}>
        <ClampedBody>
          <Prose>{value}</Prose>
        </ClampedBody>
      </div>
    );
  }
  return (
    <div className={cn("flex flex-col gap-3", className)}>
      {shared > 0 && (
        <button
          type="button"
          onClick={() => setShowEarlier((s) => !s)}
          className="flex cursor-pointer items-center gap-1 self-start text-xs text-muted-foreground transition-colors hover:text-foreground"
        >
          <IconChevronRight
            className={cn(
              "size-3 shrink-0 transition-transform",
              showEarlier && "rotate-90",
            )}
          />
          {shared} earlier {shared === 1 ? "message" : "messages"}
          {foldedByTurn ? "" : " · unchanged from the previous call"}
        </button>
      )}
      {(showEarlier ? messages.slice(0, shared) : []).map((message, i) => (
        // biome-ignore lint/suspicious/noArrayIndexKey: messages are positional and static
        <MessageBlock key={i} message={message} />
      ))}
      {shared > 0 && showEarlier && (
        <div className="flex items-center gap-2 text-[10px] font-medium uppercase tracking-wide text-muted-foreground/60">
          <span className="h-px flex-1 bg-border" />
          {foldedByTurn ? "latest turn" : "new in this call"}
          <span className="h-px flex-1 bg-border" />
        </div>
      )}
      {messages.slice(shared).map((message, i) => (
        // biome-ignore lint/suspicious/noArrayIndexKey: messages are positional and static
        <MessageBlock key={shared + i} message={message} />
      ))}
    </div>
  );
}
